#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

constexpr int64 MOD = 1'000'000'007;

int64 mulMod(int64 a, int64 b) {
    return static_cast<int64>((i128)(a % MOD) * (b % MOD) % MOD);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b;
    cin >> a >> b;

    const int64 inv2 = (MOD + 1) / 2;
    int64 sumToBMinusOne = mulMod(mulMod(b, b - 1), inv2);
    int64 sumToA = mulMod(mulMod(a, a + 1), inv2);
    int64 multiplier = (mulMod(b, sumToA) + a % MOD) % MOD;
    int64 answer = mulMod(sumToBMinusOne, multiplier);

    cout << answer << '\n';
    return 0;
}

