#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

const int64 MOD = 1000000007;
const int64 INV2 = 500000004;

int64 mod(int64 x) {
    x %= MOD;
    return x < 0 ? x + MOD : x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b;
    cin >> a >> b;

    int64 sumToBMinusOne = mod(mod(b - 1) * mod(b) % MOD * INV2 % MOD);
    int64 sumToA = mod(mod(a) * mod(a + 1) % MOD * INV2 % MOD);
    int64 total = mod(mod(b) * sumToA % MOD + mod(a));
    int64 answer = sumToBMinusOne * total % MOD;

    cout << answer << '\n';
    return 0;
}

